import{z as n,x as s,o as t,c as B,q as l,j as h,D as e,d as i,s as E,S as f,b as r}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"Kirchhoff 衍射","description":"","frontmatter":{"title":"Kirchhoff 衍射","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/kirchhoff-diffraction.md","filePath":"litho/kirchhoff-diffraction.md","lastUpdated":1791063341000}'),p={name:"litho/kirchhoff-diffraction.md"};function d(A,a,m,c,C,u){const o=s("Mermaid");return t(),B("div",null,[a[2]||(a[2]=l('<h1 id="kirchhoff-衍射" tabindex="-1">Kirchhoff 衍射 <a class="header-anchor" href="#kirchhoff-衍射" aria-label="Permalink to &quot;Kirchhoff 衍射&quot;">​</a></h1><div class="epigraph"><p>亥姆霍兹加上辐射条件，把孔径下游的场收成面积分；真正动手时还必须规定屏上的 $U$ 与法向导数——Kirchhoff 用入射场去填开口、用零去填铬，这是边值近似，不是又一条波动方程。</p><footer>—— Born &amp; Wolf, Principles of Optics 对 Kirchhoff 衍射与边值不自洽的讨论</footer></div><p><a href="/litho/helmholtz-huygens">上一课</a>已经用格林定理把亥姆霍兹写成惠更斯–菲涅尔积分，并点过 Kirchhoff / Rayleigh–Sommerfeld 的名字。缺口是：<strong>孔径平面上到底代入什么 \\(U\\) 和 \\(\\partial U/\\partial n\\)</strong>。积分核有了，边值仍是猜的。本课只钉这条近似；近场二次相位与远场傅里叶极限，留给<a href="/litho/fresnel-fraunhofer">菲涅尔与夫琅禾费</a>。不要从瑞利 CD 起笔，也不要把厚掩模电磁另起炉灶——那是后课 Kirchhoff 对严格电磁的题目。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>观察点场由包围孔径的闭曲面上的 \\(U\\) 与 \\(\\partial U/\\partial n\\) 决定。铬屏外侧的真实场既不是入射波，也不是严格为零：边缘有散射，阴影区有绕射。若坚持先解完整边值再积分，掩模开口课走不下去。Kirchhoff 的办法是：开口内用未扰动的入射场及其法向导数，不透明屏上两者都取零，半球上的贡献用辐射条件丢掉。缺口因此是这套<strong>边值替换</strong>合不合法，而不是再写一遍 \\(e^{ikR}/R\\)。</p><p>不自洽立刻出现：亥姆霍兹在平面上不能同时指定 Dirichlet 与 Neumann；开口边缘上场值跳跃，与连续解矛盾。尽管如此，当开口线度远大于波长、观察点不太靠近边缘，积分对后课已经够用。</p><h3 id="薄屏透过率是同一句话的工程写法" tabindex="-1">薄屏透过率是同一句话的工程写法 <a class="header-anchor" href="#薄屏透过率是同一句话的工程写法" aria-label="Permalink to &quot;薄屏透过率是同一句话的工程写法&quot;">​</a></h3><p>光刻把开口写成复透过率 \\(t(x,y)\\)，出射 \\(U=t\\,U_\\mathrm{inc}\\)，铬上 \\(t=0\\)。这就是 Kirchhoff 边值的物面版：不追边缘电流，只乘一层。\\(t\\) 可以带相移，仍是标量薄屏，不是三维吸收体。</p><p><span class="marginnote">「Kirchhoff 掩模」在计算光刻里几乎总是薄屏 \\(t(x,y)\\)，与本课的衍射边值是同一近似的两端。吸收体厚度与波长同量级时，边值本身错，必须换电磁求解器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>Helmholtz–Kirchhoff 公式把观察点写成</p> \\[U(P)=\\frac{1}{4\\pi}\\iint_{\\Sigma}\\Bigl(U\\frac{\\partial G}{\\partial n}-G\\frac{\\partial U}{\\partial n}\\Bigr)\\,dS,\\qquad G=\\frac{e^{ikR}}{R}. \\]<p>代入 Kirchhoff 边值，开口积分只剩入射场，倾斜因子来自 \\(\\partial G/\\partial n\\) 与球面波的夹角，Born &amp; Wolf 给出常用的 \\((1+\\cos\\theta)/2\\)。\\(k\\) 里的 \\(n\\) 仍是<a href="/litho/em-wave-index">第一课</a>的符号。</p><p>Rayleigh–Sommerfeld 换一套在孔径平面上为零的格林函数，于是只需要 \\(U\\) 或只需要 \\(\\partial U/\\partial n\\)，边值不再过定。角谱传播与它等价。本课不改仿真代码，只要求：说到「标量衍射」，默认已经做了 Kirchhoff 类边值，而不是麦克斯韦在铬角上的精确解。</p><h3 id="倾斜因子不是新的折射率" tabindex="-1">倾斜因子不是新的折射率 <a class="header-anchor" href="#倾斜因子不是新的折射率" aria-label="Permalink to &quot;倾斜因子不是新的折射率&quot;">​</a></h3><p>大角度贡献被压掉，对应倏逝分量进不去下游。这与后课「可传播频率不超过 \\(n/\\lambda\\)」同根，本课不引入 \\(\\mathrm{NA}\\)。</p><p><span class="marginnote">Kirchhoff 在边缘上场不连续，严格说会辐射不存在的电荷层。开口 \\(\\gg\\lambda\\) 时，误差集中在边缘一条带，对远场级振幅的相对贡献变小。</span></p>',17)),(t(),h(f,null,{default:e(()=>[E(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20HH%5B%22%E4%BA%A5%E5%A7%86%E9%9C%8D%E5%85%B9%E9%9D%A2%E7%A7%AF%E5%88%86%22%5D%20--%3E%20BC%5B%22%E5%BC%80%E5%8F%A3%20%2F%20%E5%B1%8F%E4%B8%8A%E7%9A%84%E8%BE%B9%E5%80%BC%22%5D%0A%20%20BC%20--%3E%20KIR%5B%22Kirchhoff%EF%BC%9A%E5%85%A5%E5%B0%84%E5%9C%BA%20vs%20%E9%9B%B6%22%5D%0A%20%20KIR%20--%3E%20THIN%5B%22%E8%96%84%E5%B1%8F%20t(x%2Cy)%22%5D%0A%20%20KIR%20--%3E%20RS%5B%22Rayleigh%E2%80%93Sommerfeld%22%5D%0A%20%20THIN%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E8%BF%91%E5%9C%BA%20%2F%20%E8%BF%9C%E5%9C%BA%E5%B1%95%E5%BC%80%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r("h2",{id:"机制",tabindex:"-1"},[i("机制 "),r("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=r("p",null,[i("入射平面波被铬截断。Kirchhoff 假装开口里的场仍是那一束平面波，屏上什么都没有；下游每一点是开口面元的相干叠加。亮暗条纹来自光程差，机制与上一课相同，只是现在明确："),r("strong",null,"错的是边值，不是核"),i("。边缘附近的真实场会修正级振幅的相位，薄铬、大开口时这项是小量。")],-1)),a[5]||(a[5]=r("p",null,[r("span",{class:"marginnote"},"数字实例：可见光 \\(\\lambda=500\\) nm 照在宽 100 μm 的缝上，开口是波长的 200 倍，受污染的边缘带只占开口的约 1%；换成宽 0.5 μm 的缝（开口 \\(\\approx\\lambda\\)），整个开口都是「边缘」，边值近似彻底失效。")],-1)),a[6]||(a[6]=r("p",null,[r("span",{class:"marginnote"},"术语翻译：倾斜因子 \\((1+\\cos\\theta)/2\\) 就是给斜着跑的光打的折扣——正对前方（\\(\\theta=0\\)）权重为 1，侧后方（\\(\\theta=180°\\)）权重为 0。它不是新折射率，只是几何角带来的衰减。")],-1)),(t(),h(f,null,{default:e(()=>[E(o,{id:"mermaid-60",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E8%BE%B9%E5%80%BC%E8%BF%91%E4%BC%BC%E4%BD%95%E6%97%B6%E5%A4%B1%E6%95%88%22%5D%20--%3E%20RATIO%5B%22%E5%BC%80%E5%8F%A3%E7%BA%BF%E5%BA%A6%20%2F%20%CE%BB%22%5D%0A%20%20RATIO%20--%3E%7C%22%E8%BF%9C%E5%A4%A7%E4%BA%8E%201%22%7C%20FINE%5B%22%E8%AF%AF%E5%B7%AE%E9%99%90%E4%BA%8E%E8%BE%B9%E7%BC%98%E4%B8%80%E6%9D%A1%E5%B8%A6%22%5D%0A%20%20FINE%20--%3E%20FAR%5B%22%E8%BF%9C%E5%9C%BA%E7%BA%A7%E6%8C%AF%E5%B9%85%E4%BB%8D%E5%8F%AF%E7%94%A8%22%5D%0A%20%20RATIO%20--%3E%7C%22%E6%8E%A5%E8%BF%91%201%22%7C%20BAD%5B%22%E6%95%B4%E4%B8%AA%E5%BC%80%E5%8F%A3%E9%83%BD%E6%98%AF%E8%BE%B9%E7%BC%98%22%5D%0A%20%20BAD%20--%3E%20EM%5B%22%E9%9C%80%E6%8D%A2%E7%94%B5%E7%A3%81%E6%B1%82%E8%A7%A3%E5%99%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=l('<p>后课把 \\(R\\) 在近场展到二次、在光瞳展到线性，全部坐在本课的开口积分上。没有边值约定，菲涅尔数没有积分对象。</p><h3 id="后课默认的接口" tabindex="-1">后课默认的接口 <a class="header-anchor" href="#后课默认的接口" aria-label="Permalink to &quot;后课默认的接口&quot;">​</a></h3><p>说到标量掩模衍射，先承认 Kirchhoff 薄屏（或等价 Rayleigh–Sommerfeld / 角谱），再问近场还是夫琅禾费。厚吸收体、偏振边界留给电磁课；本课不把 \\(t(x,y)\\) 升级成波导。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不管透镜玻璃里的逐面折射：物镜后课收成光瞳，等于在频率域乘窗。也不处理有限带宽。禁止把 Kirchhoff 说成「麦克斯韦的精确解」；不自洽是教材里写明的，不是可以忽略的脚注。更不要引用未公开的掩模电磁误差表——开口远大于波长时，标量边值已经够后课用。</p><p><span class="marginnote">常见误区：初学者容易以为 Kirchhoff 积分是「从麦克斯韦方程严格推出来的结果」。实际上格林定理只给了积分恒等式，「开口填入射场、铬填零」是人为塞进去的猜想——好用的猜想，但仍是猜想。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>惠更斯积分的核上一课已有；本课补的是开口与屏上的 Kirchhoff 边值。</li><li>开口填入射场、铬填零，与薄屏 \\(t(x,y)\\) 是同一近似。</li><li>边值过定、边缘不连续；开口 \\(\\gg\\lambda\\) 时对远场仍可用。</li><li>Rayleigh–Sommerfeld / 角谱去掉过定，仍是标量。</li><li>近场与远场如何砍相位，下一课。</li><li>出处：Born &amp; Wolf, <em>Principles of Optics</em>。</li></ul>',8))])}const F=n(p,[["render",d]]);export{g as __pageData,F as default};
